import json
import sys

input_text = sys.argv[1] if len(sys.argv) > 1 else ""
raw_tags_input = sys.argv[2] if len(sys.argv) > 2 else "[]"
raw_add_input = sys.argv[3] if len(sys.argv) > 3 else "true"
raw_backup_input = sys.argv[4] if len(sys.argv) > 4 else ""


def normalize_text(text):
    return text.replace('\r\n', '\n').replace('\\n', '\n')


def format_tags(raw_tags):
    try:
        tags = json.loads(raw_tags)
    except (json.JSONDecodeError, TypeError):
        return "Invalid tags format"

    if isinstance(tags, list) and tags:
        return ", ".join(str(tag) for tag in tags)
    return "No tags provided"


def operation_label(raw_value):
    return "Add" if str(raw_value).lower() == "true" else "Remove"


def parse_network_line(line):
    body = line[len("Network:"):].strip()
    markers = [
        " Firewall updated successfully.",
        " Firewall rule skipped",
        " Error:",
        " Validation Error:",
    ]
    matches = [(body.find(marker), marker) for marker in markers if body.find(marker) > 0]
    if not matches:
        return body, "unknown", body

    idx, marker = min(matches, key=lambda item: item[0])
    network_name = body[:idx].strip()
    detail = body[idx:].strip()

    if marker == " Firewall updated successfully.":
        category = "success"
    elif marker == " Firewall rule skipped":
        category = "skipped"
    else:
        category = "failed"

    return network_name, category, detail


def parse_results(text):
    parsed = {
        "successful_networks": [],
        "skipped_networks": [],
        "failed_networks": [],
    }
    current_org = None

    for raw_line in normalize_text(text).splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith("Results for Organization:"):
            current_org = line.split("Results for Organization:", 1)[1].strip()
            continue
        if line.startswith("Organization:") and "has no matching tags." in line:
            continue
        if line.startswith("Network:") and current_org:
            network_name, category, detail = parse_network_line(line)
            payload = {
                "organization": current_org,
                "network": network_name,
                "detail": detail,
            }
            if category == "success":
                parsed["successful_networks"].append(payload)
            elif category == "skipped":
                parsed["skipped_networks"].append(payload)
            else:
                parsed["failed_networks"].append(payload)

    return parsed


def parse_backup_entries(text):
    entries = []
    for raw_line in normalize_text(text).splitlines():
        line = raw_line.strip()
        if not line:
            continue
        try:
            payload = json.loads(line)
        except (json.JSONDecodeError, TypeError):
            continue
        if isinstance(payload, dict):
            entries.append(payload)
    return entries


def append_grouped(lines, heading, items):
    if not items:
        return
    lines.append("")
    lines.append(heading)
    current_org = None
    for item in items:
        if current_org != item['organization']:
            current_org = item['organization']
            lines.append(f"{current_org}:")
        lines.append(f"  - {item['network']} - {item['detail']}")


def build_summary(parsed, tags_string, op_label, backup_entries):
    organizations = {item['organization'] for key in parsed for item in parsed[key]}
    success_count = len(parsed['successful_networks'])
    skipped_count = len(parsed['skipped_networks'])
    failed_count = len(parsed['failed_networks'])

    lines = [
        "Bulk L3 Firewall Rule Management Summary:",
        f"Operation: {op_label}",
        f"Target Tags: {tags_string}",
        f"Organizations with matching networks: {len(organizations)}",
        f"Successful operations: {success_count}",
        f"Skipped operations: {skipped_count}",
        f"Failed operations: {failed_count}",
        f"Backup entries captured: {len(backup_entries)}",
    ]

    append_grouped(lines, "Successful Operations by Organization:", parsed['successful_networks'])
    append_grouped(lines, "Skipped Operations by Organization:", parsed['skipped_networks'])
    append_grouped(lines, "Failed Operations by Organization:", parsed['failed_networks'])
    return "\n".join(lines)


op_label = operation_label(raw_add_input)
tags_string = format_tags(raw_tags_input)
parsed_results = parse_results(input_text)
backup_entries = parse_backup_entries(raw_backup_input)
summary_text = build_summary(parsed_results, tags_string, op_label, backup_entries)
backup_json = json.dumps(backup_entries, separators=(",", ":"))

success_count = len(parsed_results['successful_networks'])
skipped_count = len(parsed_results['skipped_networks'])
failed_count = len(parsed_results['failed_networks'])
total_count = success_count + skipped_count + failed_count

if total_count == 0:
    final_status_code = 404
    final_status_message = "Not Found"
    final_error_message = "No matching networks were found for the provided tags."
elif failed_count > 0 and (success_count > 0 or skipped_count > 0):
    final_status_code = 207
    final_status_message = "Partial Success"
    final_error_message = f"{failed_count} network operation(s) failed. Review Result for details."
elif failed_count > 0:
    final_status_code = 500
    final_status_message = "Failed"
    final_error_message = f"{failed_count} network operation(s) failed. Review Result for details."
elif skipped_count > 0 and success_count == 0:
    final_status_code = 200
    final_status_message = "No Changes"
    final_error_message = ""
else:
    final_status_code = 200
    final_status_message = "Success"
    final_error_message = ""
